-- BC Minfile Occurrences
-- Generated from MinFile-pc.accdb

CREATE TABLE IF NOT EXISTS minfile_occurrences (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  MINFILNO TEXT,
  NAME1 TEXT,
  NAME2 TEXT,
  STATUS_C TEXT,
  STATUS_D TEXT,
  LATITUDE REAL,
  LONGITUDE REAL,
  UTM_ZONE TEXT,
  UTM_NORT TEXT,
  UTM_EAST TEXT,
  ELEV TEXT,
  HOSTROCK TEXT,
  DEPOSIT_CLASS TEXT,
  LAT_DEG TEXT,
  LAT_MIN TEXT,
  LAT_SEC TEXT,
  LAT_HEMI TEXT,
  LONG_DEG TEXT,
  LONG_MIN TEXT,
  LONG_SEC TEXT,
  LONG_HEMI TEXT,
  N83_ZONE TEXT,
  N83_EAST TEXT,
  N83_NORT TEXT
);


































-- Useful indexes
CREATE INDEX IF NOT EXISTS idx_minfilno ON minfile_occurrences(MINFILNO);
CREATE INDEX IF NOT EXISTS idx_status ON minfile_occurrences(STATUS_C);
CREATE INDEX IF NOT EXISTS idx_latlon ON minfile_occurrences(LATITUDE, LONGITUDE);
